                defs_by_line.setdefault(lineno, set()).add(node.id)
        self.generic_visit(node)

V().visit(func)

pairs = set()
exec_lines = []

def tracer(frame, event, arg):
    if frame.f_code is mimage._resample.__code__ and event == 'line':
        lineno = frame.f_lineno
        exec_lines.append(lineno)
        last_def = frame.f_locals.setdefault('__qa_last_def__', {})
        # uses then defs on same line
        for var in sorted(uses_by_line.get(lineno, ())):
            if var in last_def:
                pairs.add((var, last_def[var], lineno))
        for var in sorted(defs_by_line.get(lineno, ())):
            last_def[var] = lineno
    return tracer

sys.settrace(tracer)
