    TestImageResampleDefUsePairsQA().test_image_resample_def_use_pairs_case()
finally:
    sys.settrace(None)

# print debug
print('executed unique lines:', sorted(set(exec_lines)))
print('pairs:')
for p in sorted(pairs):
    print(p)
